{"function":"() => {
function rgb(s){const m=s.match(/[\d.]+/g).map(Number);return m}
function lum([r,g,b]){[r,g,b]=[r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)});return 0.2126*r+0.7152*g+0.0722*b}
function bg(e){while(e){const c=getComputedStyle(e).backgroundColor;const a=rgb(c);if(a.length<4||a[3]>0)return a;e=e.parentElement}return [255,255,255]}
function cr(a,b){const l1=lum(a),l2=lum(b);return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)}
const out=[];
const sels=['.apoio-solicitacao','#cpf-apoio','.br-breadcrumb a','.br-breadcrumb [aria-current]','.br-table td','.br-table th','.table-title','.br-pagination .page','.br-pagination .page.active','label[for=nome]','.legend, legend','.upload-button span','#documentos-apoio','.marca-govbr','.br-message .message-body','.acao-cancelar','.acao-enviar','#unidade','#servico'];
for(const s of sels){const e=document.querySelector(s);if(!e)continue;const cs=getComputedStyle(e);out.push({s,color:cs.color,bg:bg(e).join(','),cr:cr(rgb(cs.color),bg(e)),fs:cs.fontSize,fw:cs.fontWeight})}
for(const s of ['#cpf','#servico','#data-preferencial']){const e=document.querySelector(s);const p=getComputedStyle(e,'::placeholder');out.push({s:s+'::placeholder',color:p.color,cr:cr(rgb(p.color),bg(e)),fs:p.fontSize})}
return out}"}

